      properties: {
        request_id: { type: 'string', description: 'Unique identifier for the request.' },
        delay_ms: { type: 'integer', description: 'Delay in milliseconds before the operation completes (0..50).' }
      },
      required: ['request_id'],
      additionalProperties: false
    }
  }
];

function isInteger(value) {
  return typeof value === 'number' && Number.isInteger(value);
}

function validateArguments(args, schema) {
  const allowed = schema.properties || {};
  const required = schema.required || [];
  const seen = Object.keys(args);

  if (schema.additionalProperties === false) {
    for (const key of seen) {
      if (!(key in allowed)) {
        throw makeError(-32602, `Unknown field: ${key}`);
      }
    }
  }

  for (const field of required) {
    if (!(field in args) || args[field] === undefined) {
      throw makeError(-32602, `Missing required field: ${field}`);
    }
  }

  for (const key of seen) {
    if (key in allowed && allowed[key].type === 'string') {
      if (typeof args[key] !== 'string') {
        throw makeError(-32602, `Field ${key} must be a string`);
      }
    }
  }
}

export async function listTools() {
  return tools;
}

export async function callTool(name, args = {}) {
  const tool = tools.find((t) => t.name === name);
  if (!tool) {
    throw makeError(-32601, `Unknown tool: ${name}`);
  }

  validateArguments(args, tool.inputSchema);

  const { request_id, delay_ms } = args;

  if (delay_ms !== undefined) {
    if (!isInteger(delay_ms)) {
      throw makeError(-32602, 'delay_ms must be an integer');
    }
    if (delay_ms < 0) {
      throw makeError(-32602, 'delay_ms must be non-negative');
    }
  }

  if (delay_ms !== undefined && delay_ms > 50) {
    throw makeError('TIMEOUT', `Operation timed out after ${delay_ms}ms`);
  }

  if (delay_ms && delay_ms > 0) {
    await new Promise((resolve) => setTimeout(resolve, delay_ms));
  }

  return {
    request_id,
    status: 'completed'
  };
}

