import { callTool, listTools } from './server.mjs';

const eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);
let ok = true;
const check = (name, fn, pred) => fn().then(r => { if (!pred(r)) { ok = false; console.log('FAIL', name, JSON.stringify(r)); } else { console.log('PASS', name); } }).catch(e => { if (pred(e)) { console.log('PASS', name); } else { ok = false; console.log('FAIL', name, e.message, e.code); } });

// delay 0 -> completed
await check('delay 0', () => callTool('slow_operation', { request_id: 'r1', delay_ms: 0 }), r => r.status === 'completed' && r.request_id === 'r1');
// delay 30 -> completed
