// delay 50 -> completed
await check('delay 50', () => callTool('slow_operation', { request_id: 'r3', delay_ms: 50 }), r => r.status === 'completed');
// delay 51 -> TIMEOUT
await check('delay 51', () => callTool('slow_operation', { request_id: 'r4', delay_ms: 51 }), e => e.code === 'TIMEOUT');
// negative -> reject
await check('negative', () => callTool('slow_operation', { request_id: 'r5', delay_ms: -5 }), e => e.code === -32602);
// non-integer -> reject
await check('non-integer', () => callTool('slow_operation', { request_id: 'r6', delay_ms: 10.5 }), e => e.code === -32602);
// missing request_id -> reject
await check('missing request_id', () => callTool('slow_operation', {}), e => e.code === -32602);
// extra field -> reject
await check('extra field', () => callTool('slow_operation', { request_id: 'r7', foo: 'bar' }), e => e.code === -32602);
// unknown tool -> reject
await check('unknown tool', () => callTool('bogus', { request_id: 'r8' }), e => e.code === -32601);
// only request_id -> completed
await check('only request_id', () => callTool('slow_operation', { request_id: 'r9' }), r => r.status === 'completed');
// tools list
const tools = await listTools();
console.log(eq(tools[0].name, 'slow_operation') ? 'PASS listTools' : 'FAIL listTools');
if (!ok) process.exit(1);
